window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d21d2104c175f8cf"]={"versions": [{"id": "FIG-d21d2104c175f8cf", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Blockdiagramm / Architekturübersichtsdiagramm zur Darstellung der hierarchischen Abhängigkeiten zwischen den AUTOSAR-Standardfamilien. Das Diagramm verortet die Foundation als gemeinsame methodische und funktionale Basis unterhalb der Classic Platform und der Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptblöcke und zwei gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Classic Platform</strong>: Plattformstandard für tief eingebettete, echtzeitkritische Steuergeräte (ECUs); oben links platziert.\n</li><li><strong>Adaptive Platform</strong>: Plattformstandard für rechenintensive, POSIX-basierte Steuergeräte; oben rechts platziert.\n</li><li><strong>Foundation</strong>: Grundlegender AUTOSAR-Standard; als breiter Basisblock im unteren Bereich dargestellt.\n</li><li><strong>Abhängigkeitspfeile</strong>: Zwei vertikal nach unten gerichtete Pfeile (von der Classic Platform zur Foundation sowie von der Adaptive Platform zur Foundation), die die funktionale, konzeptionelle und methodische Abhängigkeit beider Plattformen von der gemeinsamen Foundation abbilden. Zwischen Classic Platform und Adaptive Platform besteht im Diagramm keine direkte Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Laufzeitsemantik. Es visualisiert keine Laufzeitkommunikation, Protokollsequenzen oder Schnittstellenaufrufe, sondern eine statische Schichtungs- und Spezifikationsabhängigkeit zur Entwicklungs- und Standardisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelle und normative Leitlinie für die AUTOSAR-Gesamtarchitektur. Spezifikationen und Konzepte der Foundation (wie gemeinsame Methodik, Protokolle und Basisanforderungen) sind für Classic Platform und Adaptive Platform verbindlich zu berücksichtigen. Classic- und Adaptive-Plattformen können unabhängig voneinander weiterentwickelt werden, müssen jedoch synchron zur jeweils zugrunde liegenden Foundation-Spezifikation spezifiziert und integriert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d6722b06f61f6e5a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Blockdiagramm / Architekturübersichtsdiagramm zur Darstellung der hierarchischen Abhängigkeiten zwischen den AUTOSAR-Standardfamilien. Das Diagramm verortet die Foundation als gemeinsame methodische und funktionale Basis unterhalb der Classic Platform und der Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptblöcke und zwei gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Classic Platform</strong>: Plattformstandard für tief eingebettete, echtzeitkritische Steuergeräte (ECUs); oben links platziert.\n</li><li><strong>Adaptive Platform</strong>: Plattformstandard für rechenintensive, POSIX-basierte Steuergeräte; oben rechts platziert.\n</li><li><strong>Foundation</strong>: Grundlegender AUTOSAR-Standard; als breiter Basisblock im unteren Bereich dargestellt.\n</li><li><strong>Abhängigkeitspfeile</strong>: Zwei vertikal nach unten gerichtete Pfeile (von der Classic Platform zur Foundation sowie von der Adaptive Platform zur Foundation), die die funktionale, konzeptionelle und methodische Abhängigkeit beider Plattformen von der gemeinsamen Foundation abbilden. Zwischen Classic Platform und Adaptive Platform besteht im Diagramm keine direkte Verbindung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Laufzeitsemantik. Es visualisiert keine Laufzeitkommunikation, Protokollsequenzen oder Schnittstellenaufrufe, sondern eine statische Schichtungs- und Spezifikationsabhängigkeit zur Entwicklungs- und Standardisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelle und normative Leitlinie für die AUTOSAR-Gesamtarchitektur. Spezifikationen und Konzepte der Foundation (wie gemeinsame Methodik, Protokolle und Basisanforderungen) sind für Classic Platform und Adaptive Platform verbindlich zu berücksichtigen. Classic- und Adaptive-Plattformen können unabhängig voneinander weiterentwickelt werden, müssen jedoch synchron zur jeweils zugrunde liegenden Foundation-Spezifikation spezifiziert und integriert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d21d2104c175f8cf", "to": "FIG-d6722b06f61f6e5a", "fr": "R19-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
